function customPageHtml(){return `<div class="mobile-title"><h1>我的</h1><i class="avatar"></i></div><section class="app-hero"><small>用户信息区</small><h2>你好，用户</h2><p>用于承接账户概览与身份信息。</p></section><div class="section-title"><b>账户服务</b></div><div class="service-list">${['设置','帮助与反馈'].map(t=>`<button class="list-row" data-target="service"><i class="fake-icon"></i><span><b>${t}</b><small>${t==='设置'?'通知、隐私与通用设置':'问题反馈和服务支持'}</small></span><em class="arrow">›</em></button>`).join('')}</div>`}
